"""Catch-up spread record (decided 2026-11-20): spread mode, per-hour record, ERROR404 hours.

Existing spreads (made when spread hours were marked estimated) are converted: their hours become
real readings (is_estimated False) and their per-hour record is written - every hour the spread
created is "empty" (old spreads only filled hours without a row), plus the catch-up hour.
"""

from django.db import migrations, models


def convert_existing_spreads(apps, schema_editor):
    CatchUpSpread = apps.get_model("wareApp", "CatchUpSpread")
    HourlySiteReading = apps.get_model("wareApp", "HourlySiteReading")
    for spread in CatchUpSpread.objects.filter(undone_at__isnull=True):
        if spread.hours_detail:
            continue
        rows = HourlySiteReading.objects.filter(
            associated_Site_id=spread.site_id, leg_id=spread.leg_id,
            reading_from__gte=spread.gap_from, reading_from__lte=spread.catch_up_at,
        )
        created = sorted(
            at for at in rows.filter(is_estimated=True, reading_from__lt=spread.catch_up_at)
            .values_list("reading_from", flat=True)
        )
        share = round(spread.share_kwh, 6)
        detail = [{"at": f"{at:%Y-%m-%dT%H:%M:%S}", "kind": "empty", "before": None, "after": share} for at in created]
        detail.append({"at": f"{spread.catch_up_at:%Y-%m-%dT%H:%M:%S}", "kind": "catch_up",
                       "before": spread.original_kwh, "after": share})
        spread.hours_detail = detail
        spread.save(update_fields=["hours_detail"])
        rows.filter(is_estimated=True).update(is_estimated=False)


def keep(apps, schema_editor):
    """Reversing keeps the hours as they are (real readings); the fields are dropped."""


